    month DATE,
    wpi_index DECIMAL(10,2),
    wpi_inflation_rate DECIMAL(6,2)
);

CREATE TABLE monetary_policy_data (
    effective_date DATE,
    repo_rate DECIMAL(5,2)
);

CREATE TABLE stock_market_data (
    date DATE,
    nifty50 DECIMAL(12,2),
    sensex DECIMAL(12,2)
);

CREATE TABLE fuel_price_data (
    date DATE,
    petrol_price DECIMAL(10,2),
    diesel_price DECIMAL(10,2)
);

