--- *************  QUESTION NO ONE ***************   ------

-- Q1. YEAR-BY-YEAR SCORECARD. HOW DID OIL, THE RUPEE AND THE STOCK MARKET CHANGE EACH YEAR? 
-- LOOK FOR: YEARS
-- WHERE ALL THREE MOVED SHARPLY (FOR EXAMPLE 2008, 2013, 2020, 2022, 2026).


---- WHEN WE WANT YEAR FRON DATE THEN WE USE **EXTRACT** FUNCTION BEFORE DATE FUNCTION LIKE
---- EXTRACT(YEAR FROM DATE).

--- WHEN WE WANT PERCENTAGE OF PRICE CHANGING WITHIN EACH YEAR THEN WE USE FORMULA
--- (THIS YEAR - LAST YEAR) / LAST YEAR *100.



WITH
      BRENT AS 
               ( 
				SELECT
					EXTRACT(YEAR FROM DATE) AS YEAR,
					ROUND( 
					AVG(BRENT_OIL_USD),2)
					AS AVG_OIL_PRICE
				FROM CRUDE_OIL_DATA
				WHERE EXTRACT(YEAR FROM DATE) >= 2007
				GROUP BY EXTRACT(YEAR FROM DATE)
				 ),

 USD AS 
       ( 
		  SELECT
		   	 EXTRACT(YEAR FROM DATE) AS YEAR,
			 ROUND ( 
			 AVG(USD_INR),2)
			 AS USD_AVERAGE
		  FROM CURRENCY_DATA
		  WHERE EXTRACT(YEAR FROM DATE) >= 2007
		  GROUP BY EXTRACT(YEAR FROM DATE)
		   ),

  STOCK AS 
          (
			SELECT
				EXTRACT(YEAR FROM DATE) AS YEAR,
				ROUND(
				AVG(NIFTY50),2)
				AS AVG_OF_NIFTY,
				ROUND(
				AVG(SENSEX),2)
				AS AVG_OF_SENSEX
			FROM STOCK_MARKET_DATA
			WHERE EXTRACT(YEAR FROM DATE) >= 2007
			GROUP BY EXTRACT(YEAR FROM DATE)
			 ),

	SCORCARD AS 
				(
 				   SELECT
						B.YEAR,
						B.AVG_OIL_PRICE,
						U.USD_AVERAGE,
						S.AVG_OF_NIFTY,
						S.AVG_OF_SENSEX,
						ROUND ( 
								(B.AVG_OIL_PRICE - LAG(B.AVG_OIL_PRICE) OVER (ORDER BY B.YEAR))
									/ LAG(B.AVG_OIL_PRICE) OVER (ORDER BY B.YEAR) * 100 ,2)
										AS BRENT_CHANGE_EACH_YEAR_PERCENTAGE,
						ROUND ( 
								 (U.USD_AVERAGE - LAG(U.USD_AVERAGE) OVER (ORDER BY B.YEAR))                              
								     / LAG(U.USD_AVERAGE) OVER (ORDER BY B.YEAR) * 100,2)
									 	AS USD_CURRENCY_CHANGES_BY_YEAR,
						ROUND (
								 (S.AVG_OF_NIFTY - LAG(S.AVG_OF_NIFTY) OVER (ORDER BY B.YEAR))
								 	/ LAG(S.AVG_OF_NIFTY) OVER (ORDER BY B.YEAR) * 100,2)
									 	AS NIFTY50_CHANGES_EVERY_YEAR,
						ROUND (
								 (S.AVG_OF_SENSEX - LAG(S.AVG_OF_SENSEX) OVER (ORDER BY B.YEAR))
								     / LAG(S.AVG_OF_SENSEX) OVER (ORDER BY B.YEAR) * 100,2)
									 	AS SENSEX_CHANGES_EVERY_YEAR
					FROM BRENT B
					JOIN USD U
						ON B.YEAR = U.YEAR
					JOIN STOCK S
						ON B.YEAR = S.YEAR
					ORDER BY B.YEAR
				)

SELECT
	YEAR,
	AVG_OIL_PRICE,
	USD_AVERAGE,
	AVG_OF_NIFTY,
	AVG_OF_SENSEX,
	BRENT_CHANGE_EACH_YEAR_PERCENTAGE,
	USD_CURRENCY_CHANGES_BY_YEAR,
	NIFTY50_CHANGES_EVERY_YEAR,
	SENSEX_CHANGES_EVERY_YEAR,
	CASE
		 WHEN (BRENT_CHANGE_EACH_YEAR_PERCENTAGE > 10 OR BRENT_CHANGE_EACH_YEAR_PERCENTAGE < -10)
		  AND (USD_CURRENCY_CHANGES_BY_YEAR > 3 OR USD_CURRENCY_CHANGES_BY_YEAR < -3)
		  AND (NIFTY50_CHANGES_EVERY_YEAR > 10 OR NIFTY50_CHANGES_EVERY_YEAR < -10)
		  THEN 'ALL THREE SHARP'
		  ELSE 'NOT ALL'
	END AS SHARP_YEAR
FROM SCORCARD
ORDER BY YEAR;


----- ---------- *********** QUESTION NO TWO  ************** -------------------

-- Q2. OIL VS RUPEE RELATIONSHIP. HOW STRONGLY DO MONTHLY BRENT CHANGES AND MONTHLY
-- USD/INR CHANGES MOVE TOGETHER, AND IS THE RELATIONSHIP STABLE OVER TIME? 
--  LOOK FOR: WHETHER THE LINK HOLDS IN ALL PERIODS OR ONLY IN SOME.


----- CORR CHECKS WHETHER TWO COLUMNS MOVE TOGETHER. IT LOOKS AT ALL ROWS AND ANSWERS ONE QUESTION: 
---- “WHEN THE FIRST COLUMN GOES UP, DOES THE SECOND COLUMN USUALLY GO UP TOO?

”---- CORR GIVES ANSWE IN-- DOUBLE PRECISION-- SO POSTGRESQL CANT GIVE ANSWER IN NUMERIC FORM SO WE,
--- ADD ::NUMERIC AFTER THE CORR QUERY.

---- DATE_TRUNC FUNCTION HELP US TO GIVE 'MONTH' FROM DATE.
--- WHEN WE ONLY WANT DATE NO OTHER THINGS WITH THAT LIKE TIMEZONE
--- THEN ADD ** :: DATE** FUNCTION AFTER DATE FUNCTION ENDS COLUMN.

---- ORDER BY MONTH ROWS BETWEEN 35 PRECEDING AND CURRENT ROW 
-- MEANING THE GROUP IS “THE 35 ROWS BEFORE THIS ONE, PLUS THIS ROW ITSELF”. THAT MAKES 36 MONTHS.

--- LINK RELATION
-- +1 MEANS OIL RISES 5% AND USD/INR RISES 5% IN THE SAME MONTH, ALWAYS.
----     **** WHEN USD/INR RISES RUPEES BECOMES WEAKER.
---- 0 MEANS OIL RISES, AND SOMETIMES USD/INR RISES, SOMETIMES FALLS.
---- -1 MEANS OIL RISES 5% AND USD/INR FALLS 5%, ALWAYS.


WITH
	BRENT AS
			(
				SELECT
					DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
					ROUND (
							AVG(BRENT_OIL_USD),2)
							   AS AVG_OIL_PRICE
				FROM CRUDE_OIL_DATA
				GROUP BY DATE_TRUNC('MONTH',DATE)
			),

	USD AS
		   (
    		   SELECT
					DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
					ROUND (
							AVG(USD_INR),2)
							   AS AVG_USD_INR
				FROM CURRENCY_DATA
				GROUP BY DATE_TRUNC('MONTH',DATE)
		   ),

	MONTHLY AS
				(
					SELECT
						B.MONTH,
						B.AVG_OIL_PRICE,
						U.AVG_USD_INR,
						ROUND (
								(B.AVG_OIL_PRICE  - LAG(B.AVG_OIL_PRICE) OVER (ORDER BY B.MONTH))
									/ LAG(B.AVG_OIL_PRICE) OVER (ORDER BY B.MONTH) * 100,2)
										AS OIL_PRICE_CHANGE_BY_MONTH,
						ROUND (
								( U.AVG_USD_INR - LAG(U.AVG_USD_INR) OVER (ORDER BY B.MONTH))
									/ LAG(U.AVG_USD_INR) OVER (ORDER BY B.MONTH) * 100,2)
										AS USD_CHANGES_BY_MONTH
					FROM BRENT B 
					JOIN USD U
						ON B.MONTH = U.MONTH

				)
	SELECT
		MONTH,
		AVG_OIL_PRICE,
		OIL_PRICE_CHANGE_BY_MONTH,
		AVG_USD_INR,
		USD_CHANGES_BY_MONTH,
		ROUND (
				CORR(OIL_PRICE_CHANGE_BY_MONTH,USD_CHANGES_BY_MONTH)
					OVER (ORDER BY MONTH ROWS BETWEEN 35 PRECEDING AND CURRENT ROW)
						::NUMERIC,4)
							AS ROLLING_36M_CORRELATION
	FROM MONTHLY
	ORDER BY MONTH;


------------- ******** QUESTION NO THREE ******* -----------------------

-- --- Q3. WHAT FOLLOWS AN OIL SPIKE? IN MONTHS WHEN BRENT ROSE MORE THAN 10%, WHAT
----  HAPPENED TO THE RUPEE AND NIFTY IN THE SAME MONTH AND THE NEXT 1 TO 3 MONTHS?


WITH
	BRENT AS
			(
				SELECT
					DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
					ROUND (
							AVG(BRENT_OIL_USD),2)
							   AS AVG_OIL_PRICE
				FROM CRUDE_OIL_DATA
				GROUP BY DATE_TRUNC('MONTH',DATE)
			),

	USD AS
		   (
    		   SELECT
					DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
					ROUND (
							AVG(USD_INR),2)
							   AS AVG_USD_INR
				FROM CURRENCY_DATA
				GROUP BY DATE_TRUNC('MONTH',DATE)
		   ),

	STOCK AS
			(
				SELECT
					DATE_TRUNC('MONTH', DATE)::DATE AS MONTH,
					ROUND ( 
						AVG(NIFTY50),2)
							AS NIFTY50_AVG
				FROM STOCK_MARKET_DATA
				GROUP BY DATE_TRUNC('MONTH',DATE)
			),

	MONTHLY_DATA AS 
					(
						SELECT
							B.MONTH,
							B.AVG_OIL_PRICE,
							U.AVG_USD_INR,
							S.NIFTY50_AVG,
							ROUND (
									(B.AVG_OIL_PRICE - LAG(B.AVG_OIL_PRICE) OVER(ORDER BY B.MONTH))
										/ LAG(B.AVG_OIL_PRICE) OVER(ORDER BY B.MONTH)* 100,2)
											AS OIL_CHANGE_PERCENT,
							ROUND (
									(U.AVG_USD_INR - LAG(U.AVG_USD_INR)OVER (ORDER BY B.MONTH))
										/ LAG(U.AVG_USD_INR)OVER (ORDER BY B.MONTH) * 100,2)
											AS USD_CHANGE_PERCENT,
							ROUND (
									(S.NIFTY50_AVG - LAG(S.NIFTY50_AVG) OVER (ORDER BY B.MONTH))
										/ LAG(S.NIFTY50_AVG) OVER (ORDER BY B.MONTH)*100,2)
											AS NIFTY50_CHANGE_PERCENT
						FROM BRENT B 
						JOIN USD U 
							ON B.MONTH = U.MONTH
						JOIN STOCK S 
							ON B.MONTH = S.MONTH
					),

	OIL_ANALYSIS AS 
					(					
						SELECT
							MONTH,
							AVG_OIL_PRICE,
							AVG_USD_INR,
							NIFTY50_AVG,
							OIL_CHANGE_PERCENT,
							USD_CHANGE_PERCENT,
							NIFTY50_CHANGE_PERCENT,
							CASE
								WHEN OIL_CHANGE_PERCENT > 10 THEN 'OIL SPIKE'
								ELSE 'NO OIL SPIKE'
							END AS OIL_SPIKE_STATUS
						FROM MONTHLY_DATA
					),

	FUTURE_ANALYSIS AS 
						(
							SELECT
								MONTH,
								AVG_OIL_PRICE,
								AVG_USD_INR,
								NIFTY50_AVG,
								OIL_CHANGE_PERCENT,
								OIL_SPIKE_STATUS,
								USD_CHANGE_PERCENT,
								NIFTY50_CHANGE_PERCENT,
								LEAD(USD_CHANGE_PERCENT, 1) OVER (ORDER BY MONTH) AS USD_CHANGE_NEXT_MONTH,
								LEAD(USD_CHANGE_PERCENT, 2)OVER (ORDER BY MONTH) AS USD_CHANGE_AFTER_2_MONTH,
								LEAD(USD_CHANGE_PERCENT, 3)OVER (ORDER BY MONTH) AS USD_CHANGE_AFTER_3_MONTH,
								LEAD(NIFTY50_CHANGE_PERCENT, 1) OVER (ORDER BY MONTH) AS NIFTY_CHANGE_NEXT_MONTH,
								LEAD(NIFTY50_CHANGE_PERCENT, 2) OVER (ORDER BY MONTH) AS NIFTY_CHANGE_AFTER_2_MONTH,
								LEAD(NIFTY50_CHANGE_PERCENT, 3) OVER (ORDER BY MONTH) AS NIFTY_CHANGE_AFTER_3_MONTH
							FROM OIL_ANALYSIS
						)
	SELECT
	ROUND (AVG(USD_CHANGE_PERCENT),2) AS USD_AVG_SAME_MONTH,
	SUM(CASE WHEN USD_CHANGE_PERCENT >0 THEN 1 ELSE 0 END) AS USD_UP_SAME_MONTH,
	ROUND (AVG(USD_CHANGE_NEXT_MONTH),2) AS USD_AVG_NEXT_MONTH,
	SUM(CASE WHEN USD_CHANGE_NEXT_MONTH > 0 THEN 1 ELSE 0 END) AS USD_UP_NEXT_MONTH,
	ROUND (AVG(USD_CHANGE_AFTER_2_MONTH),2) AS USD_AVG_AFTER_2_MONTH,
	SUM(CASE WHEN USD_CHANGE_AFTER_2_MONTH > 0 THEN 1 ELSE 0 END) AS USD_UP_AFTER_2_MONTH,
	ROUND (AVG(USD_CHANGE_AFTER_3_MONTH),2) AS USD_AVG_AFTER_3_MONTH,
	SUM(CASE WHEN USD_CHANGE_AFTER_3_MONTH > 0 THEN 1 ELSE 0 END) AS USD_UP_AFTER_3_MONTH,
	ROUND (AVG(NIFTY50_CHANGE_PERCENT),2) AS NIFTY50_CHANGE_SAME_MONTH,
	SUM(CASE WHEN NIFTY50_CHANGE_PERCENT > 0 THEN 1 ELSE 0 END) AS NIFTY50_UP_SAME_MONTH,
	ROUND (AVG(NIFTY_CHANGE_NEXT_MONTH),2) AS NIFTY50_AVG_NEXT_MONTH,
	SUM(CASE WHEN NIFTY_CHANGE_NEXT_MONTH > 0 THEN 1 ELSE 0 END) AS NIFTY50_UP_NEXT_MONTH,
	ROUND (AVG(NIFTY_CHANGE_AFTER_2_MONTH),2) AS NIFTY50_AFTER_2_MONTH,
	SUM(CASE WHEN NIFTY_CHANGE_AFTER_2_MONTH > 0 THEN 1 ELSE 0 END) AS NIFTY50_UP_AFTER_2_MONTH,
	ROUND (AVG(NIFTY_CHANGE_AFTER_3_MONTH),2) AS NIFTY50_AVG_AFTER_3_MONTH,
	SUM(CASE WHEN NIFTY_CHANGE_AFTER_3_MONTH > 0 THEN 1 ELSE 0 END ) AS NIFTY50_UP_AFTER_3_MONTH
	FROM FUTURE_ANALYSIS
	WHERE OIL_SPIKE_STATUS = 'OIL SPIKE';

		
----- ---- *********** QUESTION NO FOUR ********** -------------------------	


-- Q4. THE WORST RUPEE DAYS. ON THE 20 BIGGEST ONE-DAY RUPEE FALLS, WHAT WAS BRENT DOING IN
-- THE DAYS AROUND THEM, AND WHAT DID NIFTY DO?
-- LOOK FOR: WHETHER OIL APPEARS AROUND THESE DAYS OR OTHER EVENTS DOMINATE						


WITH   
    RUPEE_DAILY_CHANGE AS 
						(
							SELECT
								DATE,
								USD_INR,
								LAG(USD_INR) OVER(ORDER BY DATE) AS PREVIOUS_USD_INR,
								ROUND (
										(USD_INR - LAG(USD_INR) OVER(ORDER BY DATE))
											/ LAG(USD_INR) OVER(ORDER BY DATE) * 100,2)
												AS RUPEE_CHANGE_PERCENT
							FROM CURRENCY_DATA
						),

	WORST_DAYS AS 
				(
					SELECT
						DATE,
						USD_INR,
						PREVIOUS_USD_INR,
						RUPEE_CHANGE_PERCENT
						FROM RUPEE_DAILY_CHANGE
						WHERE DATE >= '2007-01-02'
						ORDER BY RUPEE_CHANGE_PERCENT DESC
						LIMIT 20		
				),

	BRENT_DAILY AS 
					(
						SELECT
							DATE,
							BRENT_OIL_USD,
							ROUND (
									(BRENT_OIL_USD - LAG(BRENT_OIL_USD,1)OVER (ORDER BY DATE)) 
										/ LAG(BRENT_OIL_USD,1)OVER (ORDER BY DATE)* 100,2)
											AS BRENT_1DAY_CHANGE_PERCENT,
							ROUND (
									(BRENT_OIL_USD - LAG(BRENT_OIL_USD,5)OVER (ORDER BY DATE)) 
										/ LAG(BRENT_OIL_USD,5)OVER (ORDER BY DATE)* 100,2)
											AS BRENT_5DAY_CHANGE_PERCENT
						FROM CRUDE_OIL_DATA
					),

	NIFTY_DAILY AS 
					(
						SELECT
							DATE,
							NIFTY50,
							ROUND (
									(NIFTY50 - LAG(NIFTY50,1)OVER (ORDER BY DATE))
										/ LAG(NIFTY50,1)OVER (ORDER BY DATE)*100,2)
											AS NIFTY_1DAY_CHANGE_PERCENT
						FROM STOCK_MARKET_DATA
					)

	SELECT
		B.DATE,
		B.BRENT_OIL_USD,
		B.BRENT_1DAY_CHANGE_PERCENT,
		B.BRENT_5DAY_CHANGE_PERCENT,
		N.NIFTY50,
		N.NIFTY_1DAY_CHANGE_PERCENT,
		W.USD_INR,
		W.PREVIOUS_USD_INR,
		W.RUPEE_CHANGE_PERCENT
	FROM WORST_DAYS W 
	LEFT JOIN BRENT_DAILY B
		ON W.DATE = B.DATE
	LEFT JOIN NIFTY_DAILY N 
		ON W.DATE = N.DATE
	ORDER BY RUPEE_CHANGE_PERCENT DESC;

						
--------- ************* QUESTION NO FIVE ************ ----------------


/* Q5. OIL TO INFLATION DELAY. DOES CPI OR WPI INFLATION FOLLOW BRENT WITH A LAG OF 0 TO 6
MONTHS, AND WHICH LAG FITS BEST? 
LOOK FOR: THE LAG WITH THE HIGHEST CORRELATION, AND WHETHER CPI AND WPI DIFFER*/


WITH BRENT_MONTHLY
		AS
			(
				SELECT
					DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
					ROUND (
							AVG(BRENT_OIL_USD),2) AS AVG_BRENT_OIL
				FROM CRUDE_OIL_DATA
				GROUP BY DATE_TRUNC('MONTH',DATE)
					
			),

	BRENT AS 
			(
				SELECT
					MONTH,
					ROUND(
							(AVG_BRENT_OIL - LAG(AVG_BRENT_OIL)OVER (ORDER BY MONTH))
								/ LAG(AVG_BRENT_OIL)OVER (ORDER BY MONTH)*100,2)
									AS OIL_CHANGE_PERCENT
					FROM BRENT_MONTHLY
			),

	CPI_MONTHLY AS 
			(
				SELECT
					MONTH,
					ROUND(
							AVG(CPI_INDEX),2) AS AVG_CPI_INDEX
					FROM INFLATION_DATA
					GROUP BY MONTH		
			),

	CPI AS 
			(
				SELECT
					MONTH,
					ROUND(
							(AVG_CPI_INDEX - LAG(AVG_CPI_INDEX) OVER (ORDER BY MONTH))
								/  LAG(AVG_CPI_INDEX) OVER (ORDER BY MONTH )* 100,2)
									AS CPI_CHANGE_PERCENT
				FROM CPI_MONTHLY
			),

	WPI_MONTHLY AS 
			(
				SELECT
					MONTH,
					ROUND(
							AVG(WPI_INDEX),2) AS AVG_WPI_INDEX
					FROM WHOLESALE_PRICE_DATA
					GROUP BY MONTH
			),

	WPI AS 
			(
				SELECT
					MONTH,
					ROUND(
							(AVG_WPI_INDEX - LAG(AVG_WPI_INDEX) OVER (ORDER BY MONTH))
								/  LAG(AVG_WPI_INDEX) OVER (ORDER BY MONTH )* 100,2)
									AS WPI_CHANGE_PERCENT
				FROM WPI_MONTHLY
			),
					

	SHIFTED AS 
				(
					SELECT
						B.MONTH,
						B.OIL_CHANGE_PERCENT,
						C.CPI_CHANGE_PERCENT,
						W.WPI_CHANGE_PERCENT,
						LAG(B.OIL_CHANGE_PERCENT,1)OVER (ORDER BY B.MONTH) AS OIL_LAG_1,
						LAG(B.OIL_CHANGE_PERCENT,2)OVER (ORDER BY B.MONTH) AS OIL_LAG_2,
						LAG(B.OIL_CHANGE_PERCENT,3)OVER (ORDER BY B.MONTH) AS OIL_LAG_3,
						LAG(B.OIL_CHANGE_PERCENT,4)OVER (ORDER BY B.MONTH) AS OIL_LAG_4,
						LAG(B.OIL_CHANGE_PERCENT,5)OVER (ORDER BY B.MONTH) AS OIL_LAG_5,
						LAG(B.OIL_CHANGE_PERCENT,6)OVER (ORDER BY B.MONTH) AS OIL_LAG_6
					FROM BRENT B 
					JOIN CPI C 
						ON B.MONTH = C.MONTH	
					JOIN WPI W 
					ON W.MONTH = C.MONTH
					
				)

	SELECT
		ROUND(CORR(OIL_CHANGE_PERCENT,CPI_CHANGE_PERCENT)::NUMERIC,4) AS CPI_CORR_LAG_0,
		ROUND(CORR(OIL_LAG_1,CPI_CHANGE_PERCENT)::NUMERIC,4) AS CPI_CORR_LAG_1,
		ROUND(CORR(OIL_LAG_2,CPI_CHANGE_PERCENT)::NUMERIC,4) AS CPI_CORR_LAG_2,
		ROUND(CORR(OIL_LAG_3,CPI_CHANGE_PERCENT)::NUMERIC,4) AS CPI_CORR_LAG_3,
		ROUND(CORR(OIL_LAG_4,CPI_CHANGE_PERCENT)::NUMERIC,4) AS CPI_CORR_LAG_4,
		ROUND(CORR(OIL_LAG_5,CPI_CHANGE_PERCENT)::NUMERIC,4) AS CPI_CORR_LAG_5,
		ROUND(CORR(OIL_LAG_6,CPI_CHANGE_PERCENT)::NUMERIC,4) AS CPI_CORR_LAG_6,
		ROUND(CORR(OIL_CHANGE_PERCENT,WPI_CHANGE_PERCENT)::NUMERIC,4) AS WPI_CORR_LAG_0,
		ROUND(CORR(OIL_LAG_1,WPI_CHANGE_PERCENT)::NUMERIC,4) AS WPI_CORR_LAG_1,
		ROUND(CORR(OIL_LAG_2,WPI_CHANGE_PERCENT)::NUMERIC,4) AS WPI_CORR_LAG_2,
		ROUND(CORR(OIL_LAG_3,WPI_CHANGE_PERCENT)::NUMERIC,4) AS WPI_CORR_LAG_3,
		ROUND(CORR(OIL_LAG_4,WPI_CHANGE_PERCENT)::NUMERIC,4) AS WPI_CORR_LAG_4,
		ROUND(CORR(OIL_LAG_5,WPI_CHANGE_PERCENT)::NUMERIC,4) AS WPI_CORR_LAG_5,
		ROUND(CORR(OIL_LAG_6,WPI_CHANGE_PERCENT)::NUMERIC,4) AS WPI_CORR_LAG_6
		
	FROM SHIFTED;



-------------- *************** QUESTION NO SIX ************** ---------------


/* Q6. INFLATION AND MARKETS UNDER DIFFERENT RBI STANCES. 
LABEL EACH MONTH AS HIKING, CUTTING OR HOLDING.
HOW DO CPI INFLATION, WPI INFLATION, USD/INR AND NIFTY BEHAVE IN EACH STANCE? */

-- THE STANCE IS SIMPLY WHAT RBI IS DOING WITH THE REPO RATE:
-- HIKING	RBI RAISED THE REPO RATE.
-- CUTTING	RBI LOWERED THE REPO RATE.     
-- HOLDING	RBI LEFT IT THE SAME.


WITH RATE_CHANGES 
				AS(				
					SELECT
						REPO_RATE,
						EFFECTIVE_DATE AS START_DATE,
						LAG(REPO_RATE)OVER (ORDER BY EFFECTIVE_DATE) AS PREVIOUS_RATE
					FROM MONETARY_POLICY_DATA
				),

	LABELLED AS
				(
					SELECT
						REPO_RATE,
						PREVIOUS_RATE,
						START_DATE,	
						CASE
							WHEN REPO_RATE > PREVIOUS_RATE THEN 'HIKING'
							WHEN REPO_RATE < PREVIOUS_RATE THEN 'CUTTING'
							ELSE 'START'
						END AS STANCE
					FROM RATE_CHANGES
				),

	STANCE_MONTHS  AS
					(
						SELECT DISTINCT
							DATE_TRUNC('MONTH',START_DATE)::DATE AS MONTH,
							STANCE
						FROM LABELLED
						WHERE STANCE <> 'START'
					),

	USD_MONTHLY AS
					(
						SELECT
							DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
							ROUND(AVG(USD_INR),2) AS AVG_USD
						FROM CURRENCY_DATA
						GROUP BY DATE_TRUNC('MONTH',DATE)
					),

	USD_CHANGE AS
					(
						SELECT
							MONTH,
							ROUND(
									(AVG_USD - LAG(AVG_USD) OVER (ORDER BY MONTH))
										/ LAG(AVG_USD) OVER (ORDER BY MONTH) * 100,2)
											AS USD_CHANGE_PERCENT
						FROM USD_MONTHLY
					),

	NIFTY_MONTHLY AS
					(
						SELECT
							DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
							ROUND(AVG(NIFTY50),2) AS AVG_NIFTY
						FROM STOCK_MARKET_DATA
						GROUP BY DATE_TRUNC('MONTH',DATE)
					),

	NIFTY_CHANGE AS
					(
						SELECT
							MONTH,
							ROUND(
									(AVG_NIFTY - LAG(AVG_NIFTY) OVER (ORDER BY MONTH))
										/ LAG(AVG_NIFTY) OVER (ORDER BY MONTH) * 100,2)
											AS NIFTY_CHANGE_PERCENT
						FROM NIFTY_MONTHLY
					),

	MONTH_TABLE AS 
					(
						SELECT
							I.MONTH,
							I.INFLATION_RATE,
							W.WPI_INFLATION_RATE,
							U.USD_CHANGE_PERCENT,
							N.NIFTY_CHANGE_PERCENT,
							COALESCE(S.STANCE,'HOLDING') AS STANCE
						FROM INFLATION_DATA I 
						LEFT JOIN STANCE_MONTHS S 
							ON I.MONTH = S.MONTH
						LEFT JOIN WHOLESALE_PRICE_DATA W 
							ON I.MONTH = W.MONTH 
						LEFT JOIN USD_CHANGE U
							ON I.MONTH = U.MONTH
						LEFT JOIN NIFTY_CHANGE N
							ON I.MONTH = N.MONTH
					)

	SELECT
		STANCE,
		COUNT(*) AS MONTHS,
		ROUND(AVG(INFLATION_RATE),2) AS AVG_CPI_INFLATION,
		ROUND(AVG(WPI_INFLATION_RATE),2) AS AVG_WPI_INFLATION,
		ROUND(AVG(USD_CHANGE_PERCENT),2) AS AVG_USD_CHANGE,
		ROUND(AVG(NIFTY_CHANGE_PERCENT),2) AS AVG_NIFTY_CHANGE
	FROM MONTH_TABLE
	GROUP BY STANCE
	ORDER BY STANCE;


------ *********** QUESTION NO SEVEN *********** ----------------


-- Q7. MARKETS AFTER RATE DECISIONS. WHAT WAS NIFTY'S AND SENSEX'S RETURN 1, 3 AND 6 MONTHS
-- AFTER RATE HIKES VERSUS RATE CUTS? 
-- CAUTION: ONLY 58 EVENTS, SO DESCRIBE PATTERNS CAREFULLY


WITH RATE_CHANGES 
				AS(				
					SELECT
						REPO_RATE,
						EFFECTIVE_DATE AS START_DATE,
						LAG(REPO_RATE)OVER (ORDER BY EFFECTIVE_DATE) AS PREVIOUS_RATE
					FROM MONETARY_POLICY_DATA
				),

	LABELLED AS
				(
					SELECT
						REPO_RATE,
						PREVIOUS_RATE,
						START_DATE,	
						CASE
							WHEN REPO_RATE > PREVIOUS_RATE THEN 'HIKING'
							WHEN REPO_RATE < PREVIOUS_RATE THEN 'CUTTING'
							ELSE 'START'
						END AS STANCE
					FROM RATE_CHANGES
				),

	STANCE_MONTHS  AS
					(
						SELECT DISTINCT
							DATE_TRUNC('MONTH',START_DATE)::DATE AS MONTH,
							STANCE
						FROM LABELLED
						WHERE STANCE <> 'START'
					),

	NIFTY_MONTHLY AS
					(
						SELECT
							DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
							ROUND(AVG(NIFTY50),2) AS AVG_NIFTY
						FROM STOCK_MARKET_DATA
						GROUP BY DATE_TRUNC('MONTH',DATE)
					),

	SENSEX_MONTHLY AS
					(
						SELECT
							DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
							ROUND(AVG(SENSEX),2) AS AVG_SENSEX
						FROM STOCK_MARKET_DATA
						GROUP BY DATE_TRUNC('MONTH',DATE)
					),

	MARKET_FUTURE AS
					(
						SELECT
							N.MONTH,
							N.AVG_NIFTY,
							LEAD(N.AVG_NIFTY,1) OVER (ORDER BY N.MONTH) AS NIFTY_AFTER_1,
							LEAD(N.AVG_NIFTY,3) OVER (ORDER BY N.MONTH) AS NIFTY_AFTER_3,
							LEAD(N.AVG_NIFTY,6) OVER (ORDER BY N.MONTH) AS NIFTY_AFTER_6,
							X.AVG_SENSEX,
							LEAD(X.AVG_SENSEX,1) OVER (ORDER BY N.MONTH) AS SENSEX_AFTER_1,
							LEAD(X.AVG_SENSEX,3) OVER (ORDER BY N.MONTH) AS SENSEX_AFTER_3,
							LEAD(X.AVG_SENSEX,6) OVER (ORDER BY N.MONTH) AS SENSEX_AFTER_6
						FROM NIFTY_MONTHLY N
						JOIN SENSEX_MONTHLY X
							ON N.MONTH = X.MONTH
					),

	EVENT_RETURNS AS
					(
						SELECT
							S.MONTH,
							S.STANCE,
							ROUND((F.NIFTY_AFTER_1 - F.AVG_NIFTY) / F.AVG_NIFTY * 100,2) AS NIFTY_RETURN_1M,
							ROUND((F.NIFTY_AFTER_3 - F.AVG_NIFTY) / F.AVG_NIFTY * 100,2) AS NIFTY_RETURN_3M,
							ROUND((F.NIFTY_AFTER_6 - F.AVG_NIFTY) / F.AVG_NIFTY * 100,2) AS NIFTY_RETURN_6M,
							ROUND((F.SENSEX_AFTER_1 - F.AVG_SENSEX) / F.AVG_SENSEX * 100,2) AS SENSEX_RETURN_1M,
							ROUND((F.SENSEX_AFTER_3 - F.AVG_SENSEX) / F.AVG_SENSEX * 100,2) AS SENSEX_RETURN_3M,
							ROUND((F.SENSEX_AFTER_6 - F.AVG_SENSEX) / F.AVG_SENSEX * 100,2) AS SENSEX_RETURN_6M
						FROM STANCE_MONTHS S
						JOIN MARKET_FUTURE F
							ON S.MONTH = F.MONTH
					)

	SELECT
		STANCE,
		COUNT(*) AS EVENTS,
		ROUND(AVG(NIFTY_RETURN_1M),2) AS AVG_NIFTY_1M,
		ROUND(AVG(NIFTY_RETURN_3M),2) AS AVG_NIFTY_3M,
		ROUND(AVG(NIFTY_RETURN_6M),2) AS AVG_NIFTY_6M,
		ROUND(AVG(SENSEX_RETURN_1M),2) AS AVG_SENSEX_1M,
		ROUND(AVG(SENSEX_RETURN_3M),2) AS AVG_SENSEX_3M,
		ROUND(AVG(SENSEX_RETURN_6M),2) AS AVG_SENSEX_6M
	FROM EVENT_RETURNS
	GROUP BY STANCE
	ORDER BY STANCE;


------- ********** QUESTION NO EIGHT *********** -----------


-- Q8. HIGH-OIL VERSUS NORMAL-OIL REGIMES. GROUP DAYS OR MONTHS INTO BRENT BUCKETS (UNDER
-- 60, 60 TO 100, OVER 100 DOLLARS). HOW DO USD/INR CHANGE, NIFTY RETURNS, CPI AND WPI
-- INFLATION COMPARE ACROSS BUCKETS? 
-- LOOK FOR: THE 2011-2014, 2022 AND 2026 HIGH-OIL PERIODS


-- STDDEV (STANDARD DEVIATION) TELLS YOU HOW MUCH THE NUMBERS JUMP AROUND. IT MEASURES THE SWING.

WITH BRENT_MONTHLY AS
					(
						SELECT
							DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
							ROUND(AVG(BRENT_OIL_USD),2) AS AVG_BRENT
						FROM CRUDE_OIL_DATA
						GROUP BY DATE_TRUNC('MONTH',DATE)
					),

	USD_MONTHLY AS
					(
						SELECT
							DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
							ROUND(AVG(USD_INR),2) AS AVG_USD
						FROM CURRENCY_DATA
						GROUP BY DATE_TRUNC('MONTH',DATE)
					),

	USD_CHANGE AS
					(
						SELECT
							MONTH,
							ROUND(
									(AVG_USD - LAG(AVG_USD) OVER (ORDER BY MONTH))
										/ LAG(AVG_USD) OVER (ORDER BY MONTH) * 100,2)
											AS USD_CHANGE_PERCENT
						FROM USD_MONTHLY
					),

	NIFTY_MONTHLY AS
					(
						SELECT
							DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
							ROUND(AVG(NIFTY50),2) AS AVG_NIFTY
						FROM STOCK_MARKET_DATA
						GROUP BY DATE_TRUNC('MONTH',DATE)
					),

	NIFTY_CHANGE AS
					(
						SELECT
							MONTH,
							ROUND(
									(AVG_NIFTY - LAG(AVG_NIFTY) OVER (ORDER BY MONTH))
										/ LAG(AVG_NIFTY) OVER (ORDER BY MONTH) * 100,2)
											AS NIFTY_CHANGE_PERCENT
						FROM NIFTY_MONTHLY
					),

	MONTH_TABLE AS
					(
						SELECT
							I.MONTH,
							B.AVG_BRENT,
							CASE
								WHEN B.AVG_BRENT < 60 THEN '1. UNDER 60'
								WHEN B.AVG_BRENT <= 100 THEN '2. 60 TO 100'
								ELSE '3. OVER 100'
							END AS OIL_BUCKET,
							I.INFLATION_RATE,
							W.WPI_INFLATION_RATE,
							U.USD_CHANGE_PERCENT,
							N.NIFTY_CHANGE_PERCENT
						FROM INFLATION_DATA I
						JOIN BRENT_MONTHLY B
							ON I.MONTH = B.MONTH
						LEFT JOIN WHOLESALE_PRICE_DATA W
							ON I.MONTH = W.MONTH
						LEFT JOIN USD_CHANGE U
							ON I.MONTH = U.MONTH
						LEFT JOIN NIFTY_CHANGE N
							ON I.MONTH = N.MONTH
					)

	SELECT
		OIL_BUCKET,
		COUNT(*) AS MONTHS,
		ROUND(AVG(AVG_BRENT),2) AS AVG_BRENT_PRICE,
		ROUND(AVG(INFLATION_RATE),2) AS AVG_CPI_INFLATION,
		ROUND(AVG(WPI_INFLATION_RATE),2) AS AVG_WPI_INFLATION,
		ROUND(AVG(USD_CHANGE_PERCENT),2) AS AVG_USD_CHANGE,
		ROUND(STDDEV(USD_CHANGE_PERCENT),2) AS STD_USD_CHANGE,
		ROUND(AVG(NIFTY_CHANGE_PERCENT),2) AS AVG_NIFTY_CHANGE,
		ROUND(STDDEV(NIFTY_CHANGE_PERCENT),2) AS STD_NIFTY_CHANGE
	FROM MONTH_TABLE
	GROUP BY OIL_BUCKET
	ORDER BY OIL_BUCKET;


--------- *********** QUESTION NO NINE ********* ----------------


-- Q9. OIL IN RUPEE TERMS. COMPUTE BRENT IN RUPEES (BRENT_OIL_USD X USD_INR). FOR EACH YEAR,
-- HOW MUCH OF THE CHANGE IN THE RUPEE COST OF OIL CAME FROM THE DOLLAR OIL PRICE AND HOW
-- MUCH FROM A WEAKER RUPEE? 
-- LOOK FOR: YEARS WHERE CURRENCY, NOT OIL, DROVE THE COST


--- ABS MEANS ABSOLUTE VALUE. IT REMOVES THE MINUS SIGN AND KEEPS ONLY THE SIZE OF THE NUMBER.

--- Number	ABS(number)
     5			5
	-5			5


WITH DAILY_RUPEE_OIL AS
					(
						SELECT
							C.DATE,
							C.BRENT_OIL_USD,
							U.USD_INR,
							C.BRENT_OIL_USD * U.USD_INR AS BRENT_IN_INR
						FROM CRUDE_OIL_DATA C
						JOIN CURRENCY_DATA U
							ON C.DATE = U.DATE
						WHERE C.DATE >= '2007-01-01'
					),

	YEARLY AS
					(
						SELECT
							EXTRACT(YEAR FROM DATE) AS YEAR,
							ROUND(AVG(BRENT_OIL_USD),2) AS AVG_BRENT_USD,
							ROUND(AVG(USD_INR),2) AS AVG_USD_INR,
							ROUND(AVG(BRENT_IN_INR),2) AS AVG_BRENT_INR
						FROM DAILY_RUPEE_OIL
						GROUP BY EXTRACT(YEAR FROM DATE)
					),

	CHANGES AS
					(
						SELECT
							YEAR,
							AVG_BRENT_USD,
							AVG_USD_INR,
							AVG_BRENT_INR,
							ROUND(
									(AVG_BRENT_USD - LAG(AVG_BRENT_USD) OVER (ORDER BY YEAR))
										/ LAG(AVG_BRENT_USD) OVER (ORDER BY YEAR) * 100,2)
											AS OIL_CHANGE_PERCENT,
							ROUND(
									(AVG_USD_INR - LAG(AVG_USD_INR) OVER (ORDER BY YEAR))
										/ LAG(AVG_USD_INR) OVER (ORDER BY YEAR) * 100,2)
											AS USD_CHANGE_PERCENT,
							ROUND(
									(AVG_BRENT_INR - LAG(AVG_BRENT_INR) OVER (ORDER BY YEAR))
										/ LAG(AVG_BRENT_INR) OVER (ORDER BY YEAR) * 100,2)
											AS RUPEE_COST_CHANGE_PERCENT
						FROM YEARLY
					)

	SELECT
		YEAR,
		AVG_BRENT_INR,
		OIL_CHANGE_PERCENT,
		USD_CHANGE_PERCENT,
		RUPEE_COST_CHANGE_PERCENT,
		ROUND(RUPEE_COST_CHANGE_PERCENT - OIL_CHANGE_PERCENT - USD_CHANGE_PERCENT,2) AS CROSS_EFFECT,
		CASE
			WHEN OIL_CHANGE_PERCENT IS NULL THEN 'NO PREVIOUS YEAR'
			WHEN ABS(USD_CHANGE_PERCENT) > ABS(OIL_CHANGE_PERCENT) THEN 'CURRENCY'
			ELSE 'OIL PRICE'
		END AS MAIN_DRIVER
	FROM CHANGES
	ORDER BY YEAR;


---------- **********8 QUESTION NO TEN ********** -------------


-- Q10. FUEL PRICE PASS-THROUGH. WHEN BRENT MOVED SHARPLY, HOW QUICKLY AND BY HOW MUCH
-- DID DELHI PETROL AND DIESEL PRICES CHANGE? COMPARE 2006-2017 WITH 2022-2026.
--  LOOK FOR: HOW MANY RETAIL REVISIONS FOLLOWED A BIG BRENT MOVE, AND THE DELAY IN DAYS.


-- INTERVAL MEANS “A LENGTH OF TIME”. YOU CAN ADD IT TO A DATE OR SUBTRACT IT FROM A DATE.

-- EXAMPLE, WITH MONTH = 2008-05-01 (THE 1ST OF THE MONTH):

-- MONTH + INTERVAL '1 MONTH' GIVES 2008-06-01.
-- - INTERVAL '1 DAY' GIVES 2008-05-31.



WITH BRENT_MONTHLY AS
					(
						SELECT
							DATE_TRUNC('MONTH',DATE)::DATE AS MONTH,
							ROUND(AVG(BRENT_OIL_USD),2) AS AVG_BRENT
						FROM CRUDE_OIL_DATA
						GROUP BY DATE_TRUNC('MONTH',DATE)
					),

	BRENT_CHANGE AS
					(
						SELECT
							MONTH,
							ROUND(
									(AVG_BRENT - LAG(AVG_BRENT) OVER (ORDER BY MONTH))
										/ LAG(AVG_BRENT) OVER (ORDER BY MONTH) * 100,2)
											AS OIL_CHANGE_PERCENT
						FROM BRENT_MONTHLY
					),

	BIG_MOVES AS
					(
						SELECT
							MONTH,
							OIL_CHANGE_PERCENT,
							(MONTH + INTERVAL '1 MONTH' - INTERVAL '1 DAY')::DATE AS MONTH_END,
							CASE
								WHEN MONTH BETWEEN '2007-01-01' AND '2017-05-01' THEN '2007-2017'
								WHEN MONTH >= '2022-05-01' THEN '2022-2026'
							END AS PERIOD
						FROM BRENT_CHANGE
						WHERE ABS(OIL_CHANGE_PERCENT) > 10
					),

	REVISIONS AS
					(
						SELECT
							DATE AS REVISION_DATE,
							PETROL_PRICE - LAG(PETROL_PRICE) OVER (ORDER BY DATE) AS PETROL_CHANGE,
							DIESEL_PRICE - LAG(DIESEL_PRICE) OVER (ORDER BY DATE) AS DIESEL_CHANGE
						FROM FUEL_PRICE_DATA
					),

	REAL_REVISIONS AS
					(
						SELECT *
						FROM REVISIONS
						WHERE PETROL_CHANGE IS NOT NULL
						  AND DIESEL_CHANGE IS NOT NULL
					),

	NEXT_REV AS
					(
						SELECT
							B.MONTH,
							B.PERIOD,
							B.OIL_CHANGE_PERCENT,
							B.MONTH_END,
							(
								SELECT MIN(X.REVISION_DATE)
								FROM REAL_REVISIONS X
								WHERE X.REVISION_DATE > B.MONTH_END
							) AS NEXT_REVISION_DATE
						FROM BIG_MOVES B
						WHERE B.PERIOD IS NOT NULL
					),

	EVENTS AS
					(
						SELECT
							N.MONTH,
							N.PERIOD,
							N.OIL_CHANGE_PERCENT,
							N.NEXT_REVISION_DATE,
							(N.NEXT_REVISION_DATE - N.MONTH_END) AS DELAY_DAYS,
							R.PETROL_CHANGE
						FROM NEXT_REV N
						LEFT JOIN REAL_REVISIONS R
							ON R.REVISION_DATE = N.NEXT_REVISION_DATE
					)

	SELECT
		PERIOD,
		COUNT(*) AS BIG_BRENT_MOVES,
		SUM(CASE WHEN DELAY_DAYS <= 30 THEN 1 ELSE 0 END) AS REVISED_WITHIN_30_DAYS,
		ROUND(AVG(DELAY_DAYS),0) AS AVG_DELAY_DAYS,
		ROUND(AVG(PETROL_CHANGE),2) AS AVG_PETROL_CHANGE,
		SUM(CASE WHEN DELAY_DAYS <= 30
				  AND SIGN(OIL_CHANGE_PERCENT) = SIGN(PETROL_CHANGE)
				 THEN 1 ELSE 0 END) AS SAME_DIRECTION_WITHIN_30
	FROM EVENTS
	GROUP BY PERIOD
	ORDER BY PERIOD;


















